#define main kernel_test_main
#include "../round2/kernel.cpp"
#undef main
#include "a_guidance_bridge.hpp"
#include <filesystem>
int main(int argc,char** argv){try{
 check(argc==2,"expected output directory");std::filesystem::create_directories(argv[1]);J evidence=J::array();
 // A real one-sided demand, compatible phase and official visitation.
 {z3::context c;auto p=c.bool_const("p"),q=c.bool_const("q"),x=c.int_const("x");auto f=(p||q)&&(q||!q)&&(x>=0)&&(x<=10);guided::AGuidanceBridge bridge(f,2,60,argv[1]);bridge.commit(bridge.ast.evaluate({{"p",1},{"q",0},{"x",0}}));z3::solver s(c);s.push();s.add(f);bridge.prepare(s,101);check(s.check()==z3::sat,"positive SAT");auto st=bridge.end_check(s);auto m=s.get_model();std::map<std::string,guided::Big> values;J projection=J::object();for(auto v:bridge.ast.vars){auto val=m.eval(v,false);auto n=v.is_bool()?guided::Big(val.is_true()):guided::numeral(val);values[v.decl().name().str()]=n;projection[v.decl().name().str()]=n.convert_to<std::string>();}auto ev=bridge.ast.evaluate(values);auto out=bridge.outcomes(ev);unsigned hits=0;for(auto a:out)for(auto t:a["targets"])hits+=t["new_covered_for_targets"].get<unsigned>();check(hits>0,"positive original coverage chain absent");evidence.push_back({{"test","positive_chain"},{"query_id",101},{"formula",f.to_string()},{"model",projection},{"outcomes",out},{"hits",hits}});}
 // Pure value must not be confused with official short-circuit visitation.
 {z3::context c;auto lead=c.bool_const("lead"),hidden=c.bool_const("hidden");guided::OriginalAst ast(lead||hidden);auto ev=ast.evaluate({{"lead",1},{"hidden",1}});check(!ev.values[ast.ids.at(hidden.id())],"unvisited branch was evaluated");z3::model m(c);auto d=hidden.decl();auto v=c.bool_val(true);m.add_const_interp(d,v);check(m.eval(hidden,false).is_true(),"hidden true value missing");evidence.push_back({{"test","value_hit_not_reached"},{"value_hit",true},{"observation_hit",false}});}
 // Raw undef followed by completion on a copy must not alter the source.
 {z3::context c;auto missing=c.bool_const("missing");z3::model original(c),copy(c);check(!original.eval(missing,false).is_true()&&!original.eval(missing,false).is_false(),"missing interpretation is defined");auto complete=copy.eval(missing,true);check(complete.is_true()||complete.is_false(),"copy completion failed");check(!original.eval(missing,false).is_true()&&!original.eval(missing,false).is_false(),"original mutated by copy completion");evidence.push_back({{"test","undef_copy_completion"},{"original_undef",true},{"copy_defined",true}});}
 // Multiple actual temporary leaves: first branch UNSAT, second provides SAT.
 {z3::context c;auto p=c.bool_const("fp"),q=c.bool_const("fq"),r=c.bool_const("fr");auto f=(p||q)&&(!p||r)&&(!p||!r);auto tactic=z3::tactic(c,"split-clause")&z3::tactic(c,"smt");auto s=tactic.mk_solver();s.add(p||q);s.add(!p||r);s.add(!p||!r);auto idx=index_of({{p,true},{q,true},{r,true}});install(s,idx,2,45,102);check(s.check()==z3::sat,"multiple leaves SAT");auto st=stats(s);clear(s);auto m=s.get_model();check(m.eval(f,true).is_true(),"multiple leaf model illegal");check(st["backend_calls"].size()>=2,"multiple leaves not exercised");evidence.push_back({{"test","multiple_leaf_provider"},{"stats",st},{"model",m.to_string()}});}
 // Repeated assignments, including rollback after incompatible phase.
 {z3::context c;auto a=c.bool_const("ra"),b=c.bool_const("rb");auto f=(a||b)&&(a||!b)&&(!a||b);z3::solver s(c);s.set("phase_selection",1u);s.push();s.add(f);auto idx=index_of({{a,false},{b,false}});install(s,idx,2,45,103);check(s.check()==z3::sat,"rollback SAT");auto st=stats(s);clear(s);auto m=s.get_model();check(m.eval(f,true).is_true(),"rollback illegal");bool popped=false;for(auto a:st["actions"])popped|=a["trailed_assignment_popped"].get<bool>();check(popped,"rollback witness absent");s.pop();s.reset();s.add(a);check(s.check()==z3::sat,"snapshot leaked after pop/reset");evidence.push_back({{"test","pop_reassign"},{"stats",st}});}
 // Both native theory entry families, without changing the decision variable.
 for(unsigned kind=0;kind<3;++kind){z3::context c;auto x=c.int_const("tx"),y=c.int_const("ty"),p=c.bool_const("tp");z3::solver s(c);s.push();auto atom=kind==0?(x<=0):(x==y);auto f=(kind==2?(!atom||p):(atom||p))&&(x>=-1)&&(x<=2)&&(y>=-1)&&(y<=2);s.add(f);auto idx=index_of({{atom,kind!=2},{p,false},{y==0,true}});install(s,idx,2,45,110+kind);check(s.check()==z3::sat,"theory entry SAT");auto st=stats(s);clear(s);auto m=s.get_model();check(m.eval(f,true).is_true(),"theory entry illegal model");evidence.push_back({{"test","theory_entry"},{"variant",kind},{"stats",st}});}
 std::cout<<J({{"passed",true},{"tests",evidence}}).dump(2)<<'\n';
 }catch(std::exception const& e){std::cerr<<e.what()<<'\n';return 1;}}
